// ZeroNote 通知捕获插件 —— 构建脚本。
//
// `tauri_plugin::Builder` 生成 permissions/autogenerated/ 下的权限文件，
// 并用 `.android_path("android")` 把 Android 库模块接进 gen/android（同 statusbar 插件）。
const COMMANDS: &[&str] = &[
  "is_enabled",
  "open_settings",
  "drain",
  "set_whitelist",
  "get_whitelist",
];

fn main() {
  tauri_plugin::Builder::new(COMMANDS)
    .android_path("android")
    .build();
}
